        mov     w16, #0x8B1D
        movk    w16, #0xBF0A, lsl #16
        add     w2, w15, w16
        ror     w2, w2, #3
        str     w2, [sp, #160]
        mov     w16, #0x5639
        movk    w16, #0x1523, lsl #16
        add     w3, w2, w16
        ror     w3, w3, #29
        str     w3, [sp, #164]
